import 'package:flutter_blue_plus/flutter_blue_plus.dart';

void startScan() {
  FlutterBluePlus.onScanResults.listen((results) {
    for (var r in results) {
      print('${r.device.remoteId}: ${r.advertisementData.advName}');
    }
  }, onError: (e) => print(e));
  FlutterBluePlus.startScan();
}
